discrete EnergyMonitoringSystem
port:
    event input real ConnectToGrid;
    event input real AbnormalEnergyDetected;
    event input real DataUploadComplete;
    event input real MonitoringTaskCompleted;
    event output real DataUploaded;
state:
    initial state Idle
        when entry() then
            statehold(5);
        end;

        when receive(ConnectToGrid) then
            transition(Running);
        end;

        when receive(MonitoringTaskCompleted) then
            transition(Idle);
        end;
    end;

    state Running
        when entry() then
            statehold(10);
        end;

        when receive(AbnormalEnergyDetected) then
            transition(DataUpload);
        out
            send(DataUploaded, 1);
        end;

        when receive(DataUploadComplete) then
            transition(DataUpload);
        out
            send(DataUploaded, 1);
        end;

        when receive(MonitoringTaskCompleted) then
            transition(Idle);
        end;
    end;

    state DataUpload
        when entry() then
            statehold(5);
        end;

        when receive(DataUploadComplete) then
            transition(Running);
        end;
    end;
end;
end;

discrete DataAnalysisAndDecisionSystem
port:
    event input real NewEnergyReportReceived;
    event input real NoImprovementSuggested;
    event input real UserConfirmedRecommendation;
    event output real RecommendationSent;
state:
    initial state Standby
        when entry() then
            statehold(5);
        end;

        when receive(NewEnergyReportReceived) then
            transition(Analyzing);
        end;
    end;

    state Analyzing
        when entry() then
            statehold(10);
        end;

        when receive(NoImprovementSuggested) then
            transition(Standby);
        end;

        when receive(NewEnergyReportReceived) then
            transition(Analyzing);
        out
            send(RecommendationSent, 1);
        end;
    end;

    state Recommendation
        when entry() then
            statehold(5);
        end;

        when receive(UserConfirmedRecommendation) then
            transition(Standby);
        end;
    end;
end;
end;

discrete PowerControlSystem
port:
    event input real AdjustmentCommandReceived;
    event input real AdjustmentCompleted;
    event input real NeedReevaluation;
    event output real AdjustmentPerformed;
state:
    initial state NormalOperation
        when entry() then
            statehold(5);
        end;

        when receive(AdjustmentCommandReceived) then
            transition(Adjusting);
        end;
    end;

    state Adjusting
        when entry() then
            statehold(10);
        end;

        when receive(AdjustmentCompleted) then
            transition(NormalOperation);
        out
            send(AdjustmentPerformed, 1);
        end;

        when receive(NeedReevaluation) then
            transition(Adjusting);
        end;
    end;
end;
end;

couple SmartPowerManagementSystem
import architectureModels.EnergyMonitoringSystem as EMS;
import architectureModels.DataAnalysisAndDecisionSystem as DADS;
import architectureModels.PowerControlSystem as PCS;
part:
    EMS emsInstance;
    DADS dadsInstance;
    PCS pcsInstance;
connection:
    connect(emsInstance.DataUploaded, dadsInstance.NewEnergyReportReceived);
    connect(dadsInstance.RecommendationSent, pcsInstance.AdjustmentCommandReceived);
end;
